            for y, x in inside:
                if y in (r0, r1) or x in (c0, c1):
                    exterior.add((y, x))
                    q.append((y, x))
            while q:
                y, x = q.pop()
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if p in inside and p not in exterior:
                        exterior.add(p)
                        q.append(p)
            hole = inside - exterior
            if not hole:
                continue

            center = ((r0 + r1) // 2, (c0 + c1) // 2)
            for y, x in hole:
                if (y, x) != center:
                    out[y][x] = 3

            top, bottom = max(0, r0 - 1), min(h - 1, r1 + 1)
            left, right = max(0, c0 - 1), min(w - 1, c1 + 1)
            for y in range(top, bottom + 1):
                for x in range(left, right + 1):
                    if (y == top or y == bottom or x == left or x == right) and grid[y][x] == 0:
                        out[y][x] = 2

    return out
